use xiom.io;
fn hand_value(cards: &Vec[Int]) -> Int {
  var total = 0;
  var aces = 0;
  var i = 0;
  while i < cards.len() {
    let v = cards.get(i).unwrap();
    if v == 1 { aces += 1; total += 11; }
    else if v >= 10 { total += 10; }
    else { total += v; };
    i += 1;
  };
  while total > 21 && aces > 0 {
    total -= 10;
    aces -= 1;
  };
  total
}

fn is_bust(total: Int) -> Bool {
  total > 21
}

fn main() -> Int {
  var hand1: Vec[Int] = Vec[Int].new();
  hand1.push(1); hand1.push(10);
  io.println(hand_value(&hand1).to_str());

  var hand2: Vec[Int] = Vec[Int].new();
  hand2.push(1); hand2.push(5); hand2.push(8);
  io.println(hand_value(&hand2).to_str());
  return 0;
}
